#!/usr/bin/env bash
# Regenerate the distributable Gen 11 stylesheet and the stack manifest.
#
# WHAT THIS BUNDLE IS, AND WHAT IT IS NOT
# ───────────────────────────────────────────────────────────────────────────
# aan-gen11.css is the SHARED LAYER: pages/_aan-family.css + _aan-components.css.
# Those two files correct and normalise components; they do not define them.
#
# Measured across the ten shipped pages (see SOURCE-MAP.md):
#
#     309 component blocks
#      36 styled outright by the shared layer
#     273 need at least one page stylesheet
#
# So this bundle alone cannot render most of the system. That is not a defect
# in the bundle — it is the shape of the product. Gen 11 keeps a great deal of
# its CSS in page stylesheets, and those stylesheets collide with each other:
# each declares its own `.app` grid, its own `--row`, its own `--cols`. They
# cannot be concatenated into one file without one page silently restyling
# another.
#
# The catalogue therefore does NOT consume a fat bundle. Each chapter is an
# iframe that loads one page's real stack from pages/, in the page's own order.
# See README.md. This script emits the manifest of those stacks alongside the
# shared bundle so a consumer outside this repo knows what to load.
#
#   usage:  bash design-system/gen11/dist/build.sh
#
set -euo pipefail

here="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
root="$(cd "$here/../../.." && pwd)"
out="$here/aan-gen11.css"
manifest="$here/stacks.json"

family="$root/pages/_aan-family.css"
components="$root/pages/_aan-components.css"

for f in "$family" "$components"; do
  [ -f "$f" ] || { echo "missing source: $f" >&2; exit 1; }
done

sha="$(cd "$root" && git rev-parse HEAD 2>/dev/null || echo 'not a git checkout')"
short="$(cd "$root" && git rev-parse --short HEAD 2>/dev/null || echo '-------')"
dirty=""
if [ -n "$(cd "$root" && git status --porcelain -- pages/ 2>/dev/null)" ]; then
  dirty=" (WORKING TREE DIRTY — pages/ modified since that commit)"
fi
date_str="$(date +%Y-%m-%d)"

{
  printf '/*!\n'
  printf ' * AAN Gen 11 — shared layer\n'
  printf ' * GENERATED FILE. Do not edit by hand.\n'
  printf ' *\n'
  printf ' * Source of truth : pages/_aan-family.css + pages/_aan-components.css\n'
  printf ' * Generated from  : %s%s\n' "$sha" "$dirty"
  printf ' * Short           : %s\n' "$short"
  printf ' * Generated on    : %s\n' "$date_str"
  printf ' *\n'
  printf ' * THIS IS THE SHARED LAYER, NOT THE WHOLE SYSTEM.\n'
  printf ' * 36 of 309 component blocks are styled outright by these two files.\n'
  printf ' * The other 273 need a page stylesheet as well — see stacks.json for\n'
  printf ' * which files each page archetype loads, and SOURCE-MAP.md for the\n'
  printf ' * per-block measurement.\n'
  printf ' *\n'
  printf ' * Regenerate with : bash design-system/gen11/dist/build.sh\n'
  printf ' * If this file and the two source files disagree, the SOURCE wins and\n'
  printf ' * this file is stale — regenerate it rather than patching it.\n'
  printf ' */\n\n'

  printf '/* ====================================================================\n'
  printf '   PART 1 of 2 — pages/_aan-family.css\n'
  printf '   The family layer: what every AAN page shares regardless of archetype.\n'
  printf '   ==================================================================== */\n'
  cat "$family"

  printf '\n\n/* ==================================================================\n'
  printf '   PART 2 of 2 — pages/_aan-components.css\n'
  printf '   The component layer: the named ui-* components and the type roles.\n'
  printf '   Loads AFTER the family layer. Order is significant.\n'
  printf '   ================================================================== */\n'
  cat "$components"
} > "$out"

# ── the stack manifest ──────────────────────────────────────────────────────
# Ten pages, eight distinct stacks. Load order is significant: the page sheet
# first, then the family layer, then the component layer.
cat > "$manifest" <<JSON
{
  "_comment": "Generated by dist/build.sh. Which stylesheets each Gen 11 page archetype loads, in order. The catalogue's specimen hosts and any consumer outside this repo must load the same files in the same order, or a component will not look like itself.",
  "_generated": "$date_str",
  "_commit": "$short$dirty",
  "shared": ["pages/_aan-family.css", "pages/_aan-components.css"],
  "stacks": {
    "av":          { "page": "pages/dealer/all-vehicles-gen11.html",        "css": ["pages/dealer/all-vehicles-gen11.css"] },
    "leads":       { "page": "pages/dealer/all-leads-gen11.html",           "css": ["pages/dealer/all-vehicles-gen11.css", "pages/dealer/all-leads-gen11.css"] },
    "lead":        { "page": "pages/dealer/single-lead-gen11.html",         "css": ["pages/dealer/all-vehicles-gen11.css", "pages/dealer/single-lead-gen11.css"] },
    "vehicle":     { "page": "pages/dealer/single-vehicle-gen11.html",      "css": ["pages/dealer/single-vehicle-gen11.css"] },
    "login":       { "page": "pages/dealer/dealer-login-gen11.html",        "css": ["pages/dealer/dealer-login-gen11.css"] },
    "queue":       { "page": "pages/staff/my-work-queue-gen11.html",        "css": ["pages/staff/my-work-queue-gen11.css"] },
    "ticket":      { "page": "pages/staff/single-ticket-gen11.html",        "css": ["pages/staff/single-ticket-gen11.css"] },
    "dealers":     { "page": "pages/staff/manage-dealers-gen11.html",       "css": ["pages/staff/manage-dealers-gen11.css"] },
    "dealer-edit": { "page": "pages/staff/dealer-edit-gen11.html",          "css": ["pages/staff/dealer-edit-gen11.css"] },
    "accounting":  { "page": "pages/staff/accounting-view-all-gen11.html",  "css": ["pages/staff/accounting-view-all-gen11.css"] }
  }
}
JSON

lines="$(wc -l < "$out" | tr -d ' ')"
echo "wrote $out"
echo "  from $short$dirty"
echo "  $lines lines"
echo "wrote $manifest"
echo "  10 pages, 8 distinct stacks"
